"""Converts `adb shell aflags list` output into flags/values/device.txt (package.flag=true|false).

Column 1 is the fully qualified flag, column 2 its current value (enabled/disabled); a staged value
in column 3 only applies after a reboot and is ignored. Lines that don't have both are skipped.
"""
import sys
from pathlib import Path

HEADER = ("# Generated by tools/hgtools/aflags.py from flags/values/device-aflags.txt\n"
          "# (`adb shell aflags list` on the target phone). Do not edit; re-run the converter.\n")


def to_device_txt(text: str) -> str:
    values = {}
    for raw in text.splitlines():
        cols = raw.strip().split()
        if len(cols) < 2 or cols[1] not in ("enabled", "disabled") or "." not in cols[0]:
            continue
        values[cols[0]] = "true" if cols[1] == "enabled" else "false"
    return HEADER + "".join(f"{k}={values[k]}\n" for k in sorted(values))


def main(argv: list[str]) -> int:
    src, dst = Path(argv[0]), Path(argv[1])
    out = to_device_txt(src.read_text(encoding="utf-8"))
    dst.write_bytes(out.encode("utf-8"))
    print(f"{dst}: {out.count(chr(10)) - 2} flags")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
